ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Job_Status__c),
    NOT(
        OR(
            /* New → Open */
            AND(
                ISPICKVAL(PRIORVALUE(Job_Status__c), "New"),
                ISPICKVAL(Job_Status__c, "Open")
            ),

            /* Open → On Hold, Closed */
            AND(
                ISPICKVAL(PRIORVALUE(Job_Status__c), "Open"),
                OR(
                    ISPICKVAL(Job_Status__c, "On Hold"),
                    ISPICKVAL(Job_Status__c, "Closed")
                )
            ),

            /* On Hold → Open, Closed */
            AND(
                ISPICKVAL(PRIORVALUE(Job_Status__c), "On Hold"),
                OR(
                    ISPICKVAL(Job_Status__c, "Open"),
                    ISPICKVAL(Job_Status__c, "Closed")
                )
            ),

            /* Closed → Open (System Admin Only) */
            AND(
                ISPICKVAL(PRIORVALUE(Job_Status__c), "Closed"),
                ISPICKVAL(Job_Status__c, "Open"),
                $Profile.Name = "System Administrator"
            )
        )
    )
)
